gbgM(){return"\u0418 \u043d\u0438\u0441\u043a\u0438\u0442\u0435, \u0438 \u0432\u0438\u0441\u043e\u043a\u0438\u0442\u0435. \u0412\u0441\u0435\u043a\u0438 \u043f\u043e\u043b\u0443\u0447\u0430\u0432\u0430 \u0435\u0434\u043d\u0430 \u0438 \u0441\u044a\u0449\u0430 \u043f\u043e\u043a\u0430\u043d\u0430 \u0441\u043b\u0435\u0434 \u043f\u0440\u0435\u0441\u0442\u043e\u0439, \u043a\u0430\u043a\u044a\u0432\u0442\u043e \u0438 \u0434\u0430 \u0435 \u0431\u0438\u043b \u0442\u043e\u0439. \u0422\u0435\u043a\u0441\u0442 \u0441 \u0432\u0440\u044a\u0437\u043a\u0430, \u0442\u0435\u043b\u0435\u0444\u043e\u043d, \u0438\u043c\u0435\u0439\u043b, \u043d\u043e\u043c\u0435\u0440 \u043d\u0430 \u043a\u043e\u043b\u0430 \u0438\u043b\u0438 \u0415\u0413\u041d \u0447\u0430\u043a\u0430 \u043f\u043e\u0434\u0434\u0440\u044a\u0436\u043a\u0430\u0442\u0430, \u043f\u0440\u0435\u0434\u0438 \u0434\u0430 \u0441\u0435 \u043f\u043e\u043a\u0430\u0436\u0435."},
